import{_ as t,o as r,c as a,a5 as n}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"异步","description":"1. 所谓\\"异步\\"，简单说就是一个任务分成两段，先执行第一段，然后转而执行其他任务，等做好了准备，再回过头执行第二段,比如，有一个任务是读取文件进行处理，异步的执行过程就是下面这样。 这种不连续的执行，就叫做异步。相应地，连续的执行，就叫做同步。 2.高阶函数 函数作为一等公民。","frontmatter":{"title":"异步","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","异步编程"],"description":"1. 所谓\\"异步\\"，简单说就是一个任务分成两段，先执行第一段，然后转而执行其他任务，等做好了准备，再回过头执行第二段,比如，有一个任务是读取文件进行处理，异步的执行过程就是下面这样。 这种不连续的执行，就叫做异步。相应地，连续的执行，就叫做同步。 2.高阶函数 函数作为一等公民。","sidebarWeight":87,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/11-异步编程/promise实现/异步.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/05-异步编程/promise实现/异步.md","filePath":"posts/JavaScript系统教程/05-异步编程/promise实现/异步.md"}'),l={name:"posts/JavaScript系统教程/05-异步编程/promise实现/异步.md"};function o(i,e,s,c,u,d){return r(),a("div",null,[...e[0]||(e[0]=[n('<div><h1 id="异步" tabindex="-1">异步 <a class="header-anchor" href="#异步" aria-label="Permalink to &quot;异步&quot;">​</a></h1><blockquote><p>本节目标：理解“异步”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 <strong>1.</strong></p></blockquote><ul><li>所谓&quot;异步&quot;，简单说就是一个任务分成两段，先执行第一段，然后转而执行其他任务，等做好了准备，再回过头执行第二段,比如，有一个任务是读取文件进行处理，异步的执行过程就是下面这样。</li></ul><p>这种不连续的执行，就叫做异步。相应地，连续的执行，就叫做同步。</p><p><strong>2.高阶函数</strong> 函数作为一等公民，可以作为参数和返回值 <strong>2.1 可以用于批量生成函数</strong> let toString = Object.prototype.toString;let isString = function (obj) { return toString.call(obj) == <code>[object String]</code>;}let isFunction = function (obj) { return toString.call(obj) == <code>[object Function]</code>;}let isType = function (type) { return function (obj) { return toString.call(obj) == <code>[object ${type}]</code>; }} <strong>2.2 可以用于需要调用多次才执行的函数</strong> let after = function(times,task){ return function(){ if(times--==1){ return task.apply(this,arguments); } }}let fn = after(3,function(){ console.log(3);});fn(); <strong>3. 异步编程的语法目标，就是怎样让它更像同步编程,有以下几种</strong></p><ul><li>回调函数实现</li><li>事件监听</li><li>发布订阅</li><li>Promise/A+ 和生成器函数</li><li>async/await</li></ul><p><strong>4. 回调</strong> 所谓回调函数，就是把任务的第二段单独写在一个函数里面，等到重新执行这个任务的时候，就直接调用这个函数 fs.readFile(&#39;某个文件&#39;, function (err, data) { if (err) throw err; console.log(data);}); 这是一个错误优先的回调函数(error-first callbacks),这也是Node.js本身的特点之一。 <strong>5 回调的问题</strong><strong>5.1 异常处理</strong> try{ //xxx}catch(e){//TODO} 异步代码时try catch不再生效 let async = function(callback){ try{ setTimeout(function(){ callback(); },1000) }catch(e){ console.log(&#39;捕获错误&#39;,e); }} async(function(){ console.log(t);}); 因为这个回调函数被存放了起来，直到下一个事件环的时候才会取出,try只能捕获当前循环内的异常，对callback异步无能为力。 Node在处理异常有一个约定，将异常作为回调的第一个实参传回，如果为空表示没有出错。 async(function(err,callback){ if(err){ console.log(err); }}); 异步方法也要遵循两个原则</p><ul><li>必须在异步之后调用传入的回调函数</li><li>如果出错了要向回调函数传入异常供调用者判断let async = function(callback){try{ setTimeout(function(){ if(success) callback(null); else callback(&#39;错误&#39;); },1000)}catch(e){ console.log(&#39;捕获错误&#39;,e);}}<strong>5.2 回调地狱</strong> ****异步多级依赖的情况下嵌套非常深，代码难以阅读的维护let fs = require(&#39;fs&#39;);fs.readFile(&#39;template.txt&#39;,&#39;utf8&#39;,function(err,template){fs.readFile(&#39;data.txt&#39;,&#39;utf8&#39;,function(err,data){ console.log(template+&#39; &#39;+data);})})</li></ul><p><strong>6. 异步流程解决方案</strong><strong>6.1 事件发布/订阅模型</strong> 订阅事件实现了一个事件与多个回调函数的关联 let fs = require(&#39;fs&#39;);let EventEmitter = require(&#39;events&#39;);let eve = new EventEmitter();let html = {};eve.on(&#39;ready&#39;,function(key,value){ html[key] = value; if(Object.keys(html).length==2){ console.log(html); }});function render(){ fs.readFile(&#39;template.txt&#39;,&#39;utf8&#39;,function(err,template){ eve.emit(&#39;ready&#39;,&#39;template&#39;,template); }) fs.readFile(&#39;data.txt&#39;,&#39;utf8&#39;,function(err,data){ eve.emit(&#39;ready&#39;,&#39;data&#39;,data); })}render(); <strong>6.2 哨兵变量</strong> let fs = require(&#39;fs&#39;); let after = function(times,callback){ let result = {}; return function(key,value){ result[key] = value; if(Object.keys(result).length==times){ callback(result); } }}let done = after(2,function(result){ console.log(result);}); function render(){ fs.readFile(&#39;template.txt&#39;,&#39;utf8&#39;,function(err,template){ done(&#39;template&#39;,template); }) fs.readFile(&#39;data.txt&#39;,&#39;utf8&#39;,function(err,data){ done(&#39;data&#39;,data); })}rende <strong>6.3 Promise/Deferred模式</strong><strong>6.4 生成器Generators/ yield</strong></p><ul><li>当你在执行一个函数的时候，你可以在某个点暂停函数的执行，并且做一些其他工作，然后再返回这个函数继续执行， 甚至是携带一些新的值，然后继续执行。</li><li>上面描述的场景正是JavaScript生成器函数所致力于解决的问题。当我们调用一个生成器函数的时候，它并不会立即执行， 而是需要我们手动的去执行迭代操作（next方法）。也就是说，你调用生成器函数，它会返回给你一个迭代器。迭代器会遍历每个中断点。</li><li>next 方法返回值的 value 属性，是 Generator 函数向外输出数据；next 方法还可以接受参数，这是向 Generator 函数体内输入数据</li></ul><p><strong>6.4.1 生成器的使用</strong> function* foo () { var index = 0; while (index &lt; 2) { yield index++; //暂停函数执行，并执行yield后的操作 }}var bar = foo(); // 返回的其实是一个迭代器 console.log(bar.next()); // { value: 0, done: false }console.log(bar.next()); // { value: 1, done: false }console.log(bar.next()); // { value: undefined, done: true } <strong>6.4.2 Co</strong> co是一个为Node.js和浏览器打造的基于生成器的流程控制工具，借助于Promise，你可以使用更加优雅的方式编写非阻塞代码。 let fs = require(&#39;fs&#39;);function readFile(filename) { return new Promise(function (resolve, reject) { fs.readFile(filename, function (err, data) { if (err) reject(err); else resolve(data); }) })}function *read() { let template = yield readFile(&#39;./template.txt&#39;); let data = yield readFile(&#39;./data.txt&#39;); return template + &#39;+&#39; + data;}co(read).then(function (data) { console.log(data);}, function (err) { console.log(err);}); function co(gen) { let it = gen(); return new Promise(function (resolve, reject) { !function next(lastVal) { let {value, done} = it.next(lastVal); if (done) { resolve(value); } else { value.then(next, reason =&gt; reject(reason)); } }(); });} <strong>6.5 Async/ await</strong> 使用async关键字，你可以轻松地达成之前使用生成器和co函数所做到的工作 <strong>6.5.1 Async的优点</strong></p><ul><li>内置执行器</li><li>更好的语义</li><li>更广的适用性</li></ul><p>let fs = require(&#39;fs&#39;);function readFile(filename) { return new Promise(function (resolve, reject) { fs.readFile(filename, &#39;utf8&#39;, function (err, data) { if (err) reject(err); else resolve(data); }) })} async function read() { let template = await readFile(&#39;./template.txt&#39;); let data = await readFile(&#39;./data.txt&#39;); return template + &#39;+&#39; + data;}let result = read();result.then(data=&gt;console.log(data)); <strong>6.5.2 async 函数的实现</strong> async 函数的实现，就是将 Generator 函数和自动执行器，包装在一个函数里。 async function read() { let template = await readFile(&#39;./template.txt&#39;); let data = await readFile(&#39;./data.txt&#39;); return template + &#39;+&#39; + data;} // 等同于function read(){ return co(function*() { let template = yield readFile(&#39;./template.txt&#39;); let data = yield readFile(&#39;./data.txt&#39;); return template + &#39;+&#39; + data; });}</p><ul><li><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Statements/async_function" target="_blank" rel="noreferrer">async_function</a>- <a href="http://www.ruanyifeng.com/blog/2015/04/generator.html" target="_blank" rel="noreferrer">generator</a> &gt; 来自 &lt;<a href="http://www.zhufengpeixun.com/grow/" target="_blank" rel="noreferrer">http://www.zhufengpeixun.com/grow/</a>&gt;</li></ul></div>',1)])])}const p=t(l,[["render",o]]);export{g as __pageData,p as default};
